mapper.select:
SELECT COUNT(1)
  FROM ADM_CODE_MST
 WHERE CODE_GRP_CD = #{code_grp_cd}
   AND CODE_CD = #{code_cd}
   AND NVL(USE_YN, 'Y') = 'Y'

   AND CODE_SEQ <> #{code_seq}

mapper.update:
UPDATE ADM_CODE_MST
   SET USE_YN = 'N',
       UPDATED_AT = SYSTIMESTAMP,
       UPDATED_BY = #{updated_by}
 WHERE CODE_SEQ = #{code_seq}
